def transform(grid):
    h, w = len(grid), len(grid[0])
    bands = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                d = c - r
                if d in bands and bands[d] != v:
                    continue
                bands[d] = v

    ds = list(bands)
    # Find the shortest repeating diagonal period consistent with all
    # the colored diagonals.
    period = 1
    for p in range(1, 2 * max(h, w) + 1):
        residues = {}
        valid = True
        for d, v in bands.items():
            q = d % p
            if q in residues and residues[q] != v:
                valid = False
                break
            residues[q] = v
        if valid and len(residues) == p:
            period = p
            break
    else:
        period = max(1, len(bands))

    residues = {}
    for d, v in bands.items():
        residues[d % period] = v

    # For any unobserved residue, continue the known color cycle in
    # increasing diagonal order.
    known = sorted(residues)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            q = (c-r) % period
            if q in residues:
                row.append(residues[q])
            else:
                nearest = min(known, key=lambda x: (q-x) % period)
                row.append(residues[nearest])
        out.append(row)
    return out
